function getIntercomFinTranslation(key, lang) {
  if (intercomFinTranslations[lang] && intercomFinTranslations[lang][key]) {
    return intercomFinTranslations[lang][key];
  }
  if (intercomFinTranslations.en && intercomFinTranslations.en[key]) {
    return intercomFinTranslations.en[key];
  }
  return null;
}

function applyIntercomFinTranslations(lang) {
  console.log(`🔥 Applying intercom-fin translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.intercom-fin.') || key.startsWith('review.common.'))) {
      const translation = getIntercomFinTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} intercom-fin translations`);
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyIntercomFinTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyIntercomFinTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyIntercomFinTranslations(currentLang);
}

console.log('✅ intercom-fin i18n loaded');
